/**
 * Bot-shaped GSC query detection (task #530).
 *
 * Google Search Console counts an impression for every SERP our result appears
 * on — including SERPs generated by automated rank-trackers and scrapers, not
 * just by humans. Those queries have a distinctive shape:
 *
 *   site:broadwayscorecard.com/show/hamilton "show score"
 *   "hadestown (broadway)" "91%" "show score"
 *
 * i.e. a `site:` operator and/or stacked quoted exact-phrases, at a good average
 * position, with LITERALLY zero clicks across thousands of impressions.
 *
 * When such a cluster starts or stops, site-wide impressions move 30%+ with no
 * change in clicks — and average position moves the WRONG way, because the
 * departing impressions sat at good positions. That combination defeated the
 * impressions-drop guard in check-seo-health.js and produced card #530
 * ("34% impressions drop", 2026-07-26), which turned out to be a third-party
 * scraper switching off on 2026-07-15, not an SEO regression:
 *
 *   clicks 2,050 -> 2,318 (+13%) while impressions fell 24.5%
 *   desktop impressions -43%, mobile +17%
 *   bot-shaped named queries 14,571 -> 2,677 impressions, 0 clicks in BOTH windows
 *   organic named queries 35,412 -> 41,650 impressions (+18%)
 *
 * These helpers are pure so the classification is testable without GSC access.
 */

'use strict';

// A `site:` / `inurl:` / `intitle:` operator is never typed by an organic visitor
// at any volume worth counting.
const OPERATOR_RE = /(^|\s)(site|inurl|intitle|inanchor|cache|related):\S/i;

// Two or more quoted exact-phrases stacked in one query is a verification probe,
// not a search. One quoted phrase alone is a real (if uncommon) human behaviour,
// so it does not qualify on its own.
function quotedPhraseCount(query) {
  const matches = query.match(/"[^"]+"/g);
  return matches ? matches.length : 0;
}

/**
 * Does this query LOOK machine-generated, independent of its click outcome?
 * @param {string} query
 * @returns {boolean}
 */
function hasBotQueryShape(query) {
  if (typeof query !== 'string' || !query.trim()) return false;
  if (OPERATOR_RE.test(query)) return true;
  return quotedPhraseCount(query) >= 2;
}

/**
 * Classify one GSC query row. Bot-shaped AND zero-click is the confident call:
 * shape alone can catch a curious human, and a click proves a human was there.
 *
 * @param {{query?: string, keys?: string[], clicks?: number, impressions?: number}} row
 * @returns {boolean}
 */
function isBotQueryRow(row) {
  if (!row) return false;
  const query = row.query ?? (Array.isArray(row.keys) ? row.keys[0] : undefined);
  if (!hasBotQueryShape(query)) return false;
  return (row.clicks || 0) === 0;
}

/**
 * Summarise the bot-shaped share of a set of GSC query rows.
 *
 * @param {Array<object>} rows GSC searchAnalytics rows dimensioned by query
 * @returns {{botImpressions: number, botQueries: number, totalImpressions: number,
 *            totalQueries: number, botShare: number, examples: string[]}}
 */
function summarizeBotQueries(rows) {
  const list = Array.isArray(rows) ? rows : [];
  let botImpressions = 0;
  let botQueries = 0;
  let totalImpressions = 0;
  const examples = [];

  for (const row of list) {
    totalImpressions += row.impressions || 0;
    if (!isBotQueryRow(row)) continue;
    botQueries++;
    botImpressions += row.impressions || 0;
    if (examples.length < 5) {
      examples.push(row.query ?? (Array.isArray(row.keys) ? row.keys[0] : ''));
    }
  }

  return {
    botImpressions,
    botQueries,
    totalImpressions,
    totalQueries: list.length,
    botShare: totalImpressions > 0 ? botImpressions / totalImpressions : 0,
    examples,
  };
}

// Below this, the named-query sample is too thin to extrapolate from and we fall
// back to treating the raw observed delta as-is rather than amplifying noise.
const MIN_QUERY_COVERAGE = 0.05;

/**
 * Does a fall in bot-shaped impressions account for (most of) a site-wide
 * impressions decline? Used to suppress the impressions_drop alert.
 *
 * The delta has to be scaled before it can be compared. GSC's `query` dimension
 * only NAMES about 30% of a site's impressions — Google anonymises rare queries,
 * and machine-generated queries are rare almost by construction — so the bot
 * impressions we can see are a fraction of the ones that actually happened. In
 * the 2026-07 event the visible bot decline was 11,894 against a site-wide
 * decline of 40,462 (29%), which looks unconvincing until you divide by the
 * 30.3% query coverage in the same window: ~39,254, i.e. essentially all of it.
 *
 * Scaling by 1/coverage assumes bot queries are anonymised at the same rate as
 * everything else. They are almost certainly anonymised MORE (they are rarer),
 * so this is the conservative direction.
 *
 * @param {object} args
 * @param {number} args.impressionsDelta    site-wide impressions LOST (positive when down)
 * @param {number} args.botImpressionsDelta bot-shaped impressions LOST (positive when down)
 * @param {number} [args.namedImpressions]  impressions the query dimension named
 * @param {number} [args.totalImpressions]  site-wide impressions in the same window
 * @param {number} [args.threshold]         share of the decline the bot fall must cover
 * @returns {boolean}
 */
function botDropExplainsDecline({
  impressionsDelta,
  botImpressionsDelta,
  namedImpressions,
  totalImpressions,
  threshold = 0.5,
}) {
  if (!(impressionsDelta > 0)) return false;
  if (!(botImpressionsDelta > 0)) return false;

  let coverage = 1;
  if (namedImpressions > 0 && totalImpressions > 0) {
    coverage = Math.min(1, Math.max(MIN_QUERY_COVERAGE, namedImpressions / totalImpressions));
  }
  const scaledBotDelta = botImpressionsDelta / coverage;

  return scaledBotDelta >= impressionsDelta * threshold;
}

module.exports = {
  hasBotQueryShape,
  isBotQueryRow,
  summarizeBotQueries,
  botDropExplainsDecline,
  quotedPhraseCount,
};
